// TestGeneratedReadmeMatchesBehavior ties the mounted README.md (generated by
// internal/fs.generateReadme) to actual filesystem behavior, so the doc can't
// silently drift from the code again. It guards the specific bug the code review
// surfaced: the README claimed _create reads "return empty" while every _create
// node actually returns EACCES.
func TestGeneratedReadmeMatchesBehavior(t *testing.T) {
	data, err := os.ReadFile(filepath.Join(mountPoint, "README.md"))
	if err != nil {
		t.Fatalf("read README.md: %v", err)
	}
	readme := string(data)

	// The old, inaccurate claim must not reappear.
	if strings.Contains(readme, "returns empty (size 0)") {
		t.Error("README claims _create reads return empty, but _create nodes return EACCES")
	}

	// It should document the surfaces this branch added so agents learn about them.
	// "recent created updates" guards the updates trio: updates/ directories were
	// the last create surface without .error/.last, which made the README's global
	// "every writable directory has a .error" claim false there.
	// "relations, updates" pins updates' membership in the .last surface list;
	// "creates one item" pins the per-write-cycle semantics (each write to
	// _create creates another item — the old node-level buffers silently
	// swallowed the second write, so nothing documented it).
	// "targeted catalog refresh" pins the stale-catalog self-healing doc (#246):
	// a local name→ID miss refreshes the catalog once and retries before .error.
	// "outcome: failed" pins the .last outcome-log contract (#370): a failed
	// create appends a countable failure entry rather than .error collapsing to
	// only the last failure of a batch.
	// "subteams/" pins the team-hierarchy surface: teams/ stays flat, so a
	// sub-team is only discoverable through the symlinks and team.md's
	// parent/subteams keys — a README that omits them hides the whole edge.
	for _, want := range []string{".last", "issue.meta", "initiative.meta", "recent/", "recent created updates", "relations, updates", "creates one item", "targeted catalog refresh", "outcome: failed", "subteams/"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q", want)
		}
	}

	// Team moves (#429): team: became editable, and it is the only edit that
	// changes where the file lives. The re-numbering is the part an agent cannot
	// discover by trying — it caches a path, the move invalidates it, and without
	// the doc that reads as the filesystem losing the issue. The same-edit
	// resolution scope is the other trap: a status: valid in the source team may
	// not exist in the destination.
	for _, want := range []string{"<team_moves>", "RE-NUMBERS", "DESTINATION team"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q (team-move contract)", want)
		}
	}
	// And team: really is in the editable file, not the read-only sidecar — the
	// README's frontmatter template is what an agent copies from.
	if !strings.Contains(readme, "team: ENG") {
		t.Error("README's issue.md template does not document the editable team: field")
	}

	// The exhaustive-key rule (#426): issue.md rejects a key it does not accept
	// rather than dropping it. The doc has to say so, because the behavior it
	// replaced — accept, apply nothing, and lose the key on the next render —
	// is what an agent will otherwise assume from a 0 exit. "EXHAUSTIVE" pins the
	// claim; "no third outcome" pins its consequence, which is the part that
	// makes a successful write trustworthy.
	for _, want := range []string{"EXHAUSTIVE", "no third outcome"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q (unknown-frontmatter-key contract)", want)
		}
	}

	// Atomic save (#438): every editor and the Edit/Write tools save by writing a
	// temp file and renaming it over the target, and the README has to teach the
	// two things that path's failures depend on — that the SAVE happens at the
	// rename, and that an unrenamed scratch file is DISCARDED rather than
	// created. Without the second, "echo x > docs/notes.txt saved nothing" reads
	// as a filesystem bug instead of a documented contract.
	for _, want := range []string{"<atomic_save>", "SCRATCH", "DISCARDED", "at the RENAME"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q (atomic-save contract)", want)
		}
	}

	// The project/initiative external-link surface (#249): the README must teach
	// the links/ directory and its "URL [label]" write contract, and the *.link
	// files must really be read-only (a documented write-only/read-only surface
	// that lies is the exact failure this test exists to prevent).
	for _, want := range []string{"links/", ".link", "URL [label]"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q (project/initiative links surface)", want)
		}
	}

	// The meta split moved server fields out of the editable files. The README's
	// frontmatter templates must not document them as editable-file fields, or an
	// agent will look for/edit fields that no longer live there (the exact "the
	// generated README silently lies" failure this test exists to prevent). The
	// initiative template used to show slug:/targetDate:/owner: inside initiative.md.
	for _, leak := range []string{"slug: 77d439e363bb", "targetDate:"} {
		if strings.Contains(readme, leak) {
			t.Errorf("README documents %q as an editable-file field, but it moved to .meta", leak)
		}
	}

	// The collection meta split: every collection item {base}.md is documented
	// with a read-only {base}.meta sidecar, and comment .md files are the pure
	// body. The README's structure map must teach both.
	for _, want := range []string{"{id}.meta", "{slug}.meta", "{name}.meta", "no frontmatter", "*.meta sidecar"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q (collection meta split)", want)
		}
	}
	// And the documented surfaces must really behave that way: a doc's .meta
	// exists, reads, and rejects writes; the comment .md has no frontmatter. The
	// issue comes from the workspace (someIssueID), not a hardcoded TST-1 — under
	// a live key that path does not exist, and these ReadDir-guarded checks then
	// pass by doing nothing (#395).
	readmeIssueID := someIssueID(t)
	if entries, err := os.ReadDir(docsPath(testTeamKey, readmeIssueID)); err == nil {
		for _, e := range entries {
			if isControlFile(e.Name()) || !strings.HasSuffix(e.Name(), ".md") {
				continue
			}
			metaPath := docFilePath(testTeamKey, readmeIssueID, strings.TrimSuffix(e.Name(), ".md")+".meta")
			if _, err := os.ReadFile(metaPath); err != nil {
				t.Errorf("README documents doc .meta sidecars but %s is unreadable: %v", metaPath, err)
			}
			if err := os.WriteFile(metaPath, []byte("x"), 0644); err == nil {
				t.Errorf("README documents %s as read-only but it accepted a write", metaPath)
			}
			break
		}
	}
	if entries, err := os.ReadDir(commentsPath(testTeamKey, readmeIssueID)); err == nil {
		for _, e := range entries {
			if isControlFile(e.Name()) || !strings.HasSuffix(e.Name(), ".md") {
				continue
			}
			content, err := os.ReadFile(commentFilePath(testTeamKey, readmeIssueID, e.Name()))
			if err == nil && strings.HasPrefix(string(content), "---") {
				t.Errorf("README documents comment .md as frontmatter-free, but %s carries frontmatter", e.Name())
			}
			break
		}
	}

	// Spot-check the documented _create read behavior against the real node:
	// reading issues/_create must fail (write-only), matching the README.
	if _, err := os.ReadFile(issuesPath(testTeamKey) + "/_create"); err == nil {
		t.Error("issues/_create is readable, but README documents it as write-only")
	}

	// The create tail unified the failure model and closed the .last gap: the
	// README must document EAGAIN/ENOENT/EMSGSIZE alongside EINVAL/EIO, and must
	// not resurrect the "attachments and relations don't report to .last" carve-out.
	for _, want := range []string{"EAGAIN", "ENOENT", "EMSGSIZE", "EDQUOT"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README failure model does not mention %q", want)
		}
	}
	// #409: EDQUOT is only worth a new errno if the bullet says what to DO. A bare
	// "-> EDQUOT" would leave an agent exactly where "invalid argument" left it,
	// and the one thing that distinguishes it from the EAGAIN above is that
	// retrying is futile.
	for _, want := range []string{"plan/usage limit", "will NOT help"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README documents EDQUOT without its next action: missing %q", want)
		}
	}
	if strings.Contains(readme, "instead surface the result") {
		t.Error("README carves attachments/relations out of .last, but every create surface reports to .last now")
	}

	// #397/#398: the two empty-write verdicts. Both are things an agent discovers
	// only by doing the destructive thing, so the README has to say them up front —
	// and they must not drift back into the old behavior (an emptied issue.md
	// clearing five fields; an empty project body returning a retryable EIO).
	for _, want := range []string{"EMPTIED editable file", "KEEPS ITS CURRENT", "Linear cannot apply"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README failure model does not document the empty-write contract: missing %q", want)
		}
	}
	// #472: the third verdict of the same family. A zero-filled write is the one
	// an agent makes without noticing — a pwrite past EOF, a grow-resize — and
	// before the guard it cleared every removable field at exit 0, so the README
	// has to name it too.
	for _, want := range []string{"ZERO-FILLED editable file", "NUL", "offset 0"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README failure model does not document the zero-fill rejection: missing %q", want)
		}
	}
	// #399: EAGAIN covers two situations with different safe follow-ups, and the
	// README must not collapse them back into one "the write did not take effect"
	// promise — that promise is false for a request interrupted after it was sent,
	// and acting on it duplicates the entity.
	for _, want := range []string{"interrupted", "UNKNOWN"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not distinguish the two EAGAIN outcomes: missing %q", want)
		}
	}
	// And the documented behavior is real. The probe targets a doc .md rather
	// than issue.md for two reasons: the guard lives on the shared edit-flush
	// shell, so any editable file proves it; and a rejected write leaves .error
	// populated, which on issue.md would be shared-mount residue another test
	// reads. A collection's .error is explicitly not assumed empty by this suite
	// (see TestErrorFileExposedOnWritableSurfaces).
	//
	// Emptying goes through O_TRUNC rather than the atomic-rename helper because
	// O_TRUNC is deterministic here: the truncate is a real setattr the kernel
	// cannot serve from cache, so the close-time Flush always runs and hands back
	// its errno. (docs/ does accept a scratch temp file now — #438 — so the
	// rename path would work too; it just proves less about THIS guard, which
	// lives on the shared edit-flush shell either way.)
	//
	// The bytes are read before and after, which does double duty. It pins the
	// other half of the README's promise — the file KEEPS ITS CURRENT CONTENTS,
	// so the "re-read it" recovery works — and it proves this probe leaves the
	// SHARED mount as it found it. Without the restore, the rejected flush left
	// this node dirty and empty for the rest of the run, and the next test to
	// read the same doc (t6_conformance's editable-only check) would assert
	// against zero bytes and pass vacuously.
	if docTarget, err := firstWritableFile(docsPath(testTeamKey, readmeIssueID)); err == nil {
		before, err := os.ReadFile(docTarget)
		if err != nil {
			t.Fatalf("read %s before emptying it: %v", docTarget, err)
		}
		f, err := os.OpenFile(docTarget, os.O_WRONLY|os.O_TRUNC, 0644)
		if err != nil {
			t.Fatalf("open %s to empty it: %v", docTarget, err)
		}
		if cerr := f.Close(); !errors.Is(cerr, syscall.EINVAL) {
			t.Errorf("README says an emptied editable file is EINVAL, but emptying %s returned %v",
				docTarget, cerr)
		}
		after, err := os.ReadFile(docTarget)
		if err != nil {
			t.Fatalf("read %s after the rejected empty write: %v", docTarget, err)
		}
		if !bytes.Equal(before, after) {
			t.Errorf("%s reads back as %d bytes after a rejected empty write, want its original %d — "+
				"the README tells the writer to re-read the file to recover its contents",
				docTarget, len(after), len(before))
		}
	}

	// #5: project/initiative bodies map to the long content field, not the ≤255
	// description; the README must not tell writers the body is the description
	// (which silently rejected any real write-up), and must place description in
	// the read-only .meta.
	if !strings.Contains(readme, "the body maps to the long content") {
		t.Error("README does not document that project/initiative bodies map to content")
	}
	if strings.Contains(readme, "the body maps to the description)") {
		t.Error("README still claims a project/initiative body maps to the ≤255 description field (#5)")
	}

	// #379: a successful write whose body Linear reformatted leaves an
	// informational .error note, and a later read shows the stored formatting
	// rather than the written bytes. Both are contract an agent gets wrong by
	// default — it reads the note as a failed write, and it find-and-replaces
	// against a now-stale in-context copy — so the README must state them.
	for _, want := range []string{
		"saved, but Linear reformatted the markdown",
		"Re-read the file before any follow-up edit",
		"a later read shows",
	} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not document the server-side reformat contract: missing %q", want)
		}
	}
	// The written bytes are pinned across the atomic-save re-Lookup, so an
	// immediate re-read shows the agent's own bytes, never Linear's formatting.
	// The two places the README describes the reformat must agree on that timing.
	if strings.Contains(readme, "Re-read the file to see what it stored") {
		t.Error("README still tells an agent an immediate re-read shows Linear's stored formatting (#379 pins the written bytes)")
	}

	// Project labels (#130): the README must teach the catalog surface and the
	// assignment rules ("one child" pins group exclusivity; "retired" pins the
	// lifecycle; the reference-files line must point at the catalog).
	for _, want := range []string{"project-labels.md", "one child", "retired", "Validated project fields"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not mention %q", want)
		}
	}
	// And the documented surface must really exist, read-only, with the
	// group marker the rules refer to.
	catalog, err := os.ReadFile(filepath.Join(mountPoint, "project-labels.md"))
	if err != nil {
		t.Fatalf("README documents project-labels.md but it is unreadable: %v", err)
	}
	if !strings.Contains(string(catalog), "group") {
		t.Error("project-labels.md does not carry the group marker the README describes")
	}
	if info, err := os.Stat(filepath.Join(mountPoint, "project-labels.md")); err == nil && info.Mode().Perm() != 0444 {
		t.Errorf("project-labels.md mode = %v, want 0444 (README: read-only)", info.Mode().Perm())
	}

	// #475: the freshness contract. Nothing pinned its predecessor ("Cache TTL:
	// 60s for issues, 10min for states/labels/users"), which is how it outlived
	// the in-memory cache it described. Two claims here are ones an agent acts
	// on: "never blocks on" pins that a read is served locally and never waits
	// on Linear (so a hung workspace is not a hung mount); "still returns the
	// bytes it has" plus "re-read to see it" pin the stale-while-revalidate
	// half — a stale read hands back what it has and refreshes behind you, so
	// someone else's edit needs a LATER read, not a longer one.
	for _, want := range []string{"never blocks on", "still returns the bytes it has", "re-read to see it"} {
		if !strings.Contains(readme, want) {
			t.Errorf("README does not document the freshness contract: missing %q", want)
		}
	}

	// #366: the agent self-reporting protocol is opt-in (USER_FEEDBACK). The
	// suite mounts without it, so the served README must not carry it — a
	// default mount never tells an agent to file issues on this repo. The
	// flag-on shape is pinned by internal/fs.TestGenerateReadmeFeedbackFlag.
	for _, leak := range []string{"agent_feedback_protocol", "dx-friction", "gh issue create"} {
		if strings.Contains(readme, leak) {
			t.Errorf("README carries %q without USER_FEEDBACK set (the protocol must be opt-in)", leak)
		}
	}
}

// TestUserFeedbackReadmeThroughMount is the flag-on half of #366's acceptance:
// with config.UserFeedback set, the README served through a real mount carries
// the self-reporting protocol. It mounts its own filesystem because the suite's
// shared mount deliberately runs with the flag off (see above). No store is
// needed — the README is a pure render.
func TestUserFeedbackReadmeThroughMount(t *testing.T) {
	mnt, err := os.MkdirTemp("", "linearfs-test-feedback-*")
	if err != nil {
		t.Fatalf("create mount point: %v", err)
	}
	lfs, err := fs.NewLinearFS(&config.Config{APIKey: "feedback-mode-key", UserFeedback: true}, false)
	if err != nil {
		os.RemoveAll(mnt)
		t.Fatalf("create linearfs: %v", err)
	}
	srv, err := fs.MountFS(mnt, lfs, false)
	if err != nil {
		lfs.Close()
		os.RemoveAll(mnt)
		t.Fatalf("mount filesystem: %v", err)
	}
	t.Cleanup(func() {
		unmounted := unmountBestEffort(t, srv, mnt)
		lfs.Close()
		// Only walk the directory once it is really a plain directory again.
		// RemoveAll on a live mount readdirs *through* the filesystem, and this
		// FS deliberately has no store behind it, so a lookup there would panic
		// the whole test binary (go-fuse does not recover in the request path).
		if !unmounted {
			t.Logf("leaving %s in place: still mounted", mnt)
			return
		}
		os.RemoveAll(mnt)
	})

	data, err := os.ReadFile(filepath.Join(mnt, "README.md"))
	if err != nil {
		t.Fatalf("read README.md: %v", err)
	}
	readme := string(data)

	// The protocol must be there, actionable: the label, the create command, the
	// dedup search, and the receipt the human sees.
	for _, want := range []string{
		"<agent_feedback_protocol>",
		"dx-friction",
		"gh issue create --repo jra3/linear-fuse",
		"gh issue list --repo jra3/linear-fuse --search",
		"filed linear-fuse bug #N",
	} {
		if !strings.Contains(readme, want) {
			t.Errorf("USER_FEEDBACK README does not mention %q", want)
		}
	}
	// And it is append-only: the normal doc is still fully there.
	for _, want := range []string{"<directory_structure>", "</claude_code_instructions>"} {
		if !strings.Contains(readme, want) {
			t.Errorf("USER_FEEDBACK README lost %q; the protocol must only append", want)
		}
	}
}

// unmountBestEffort tears down a test's own mount the way the suite's cleanup()
// does: unmount, and on EBUSY (a straggling fd) retry once, then lazy-detach so
// the kernel completes the unmount when the last fd closes. It reports whether
// the path is a plain directory again — a caller must not walk or remove it
// otherwise, since that would issue FUSE requests against a torn-down server.
func unmountBestEffort(t *testing.T, srv *fuse.Server, mnt string) bool {
	t.Helper()
	err := srv.Unmount()
	if err == nil {
		return true
	}
	time.Sleep(200 * time.Millisecond)
	if err := srv.Unmount(); err == nil {
		return true
	}
	// An unprivileged umount2 is not permitted on FUSE; the setuid helper
	// lazy-detaches instead (darwin has no fusermount3).
	cmd := exec.Command("fusermount3", "-uz", mnt)
	if runtime.GOOS == "darwin" {
		cmd = exec.Command("umount", "-f", mnt)
	}
	if out, lerr := cmd.CombinedOutput(); lerr != nil {
		t.Logf("Warning: unmount %s failed (%v), lazy detach failed too (%v: %s); clean it manually", mnt, err, lerr, out)
		return false
	}
	// Lazy: the mount goes away when the last fd closes, which may be after
	// this returns, so the directory is not safe to walk yet.
	t.Logf("Note: %s was busy at cleanup; lazy-detached", mnt)
	return false
}
